mapper.select:
SELECT p.*
FROM products p
WHERE p.category_id IN (
SELECT c1.category_id
FROM category c1
WHERE c1.category_id = #{categoryId}
    OR c1.parent_id = #{categoryId}
    OR c1.parent_id IN (
SELECT c2.category_id
FROM category c2
WHERE c2.parent_id = #{categoryId}
)
)
ORDER BY p.created_at DESC

WITH RECURSIVE cat_tree AS ( SELECT category_id FROM category WHERE category_id = #{categoryId}
UNION ALL
SELECT c.category_id FROM category c JOIN cat_tree ct ON c.parent_id = ct.category_id ) SELECT p.* FROM products p JOIN cat_tree ct ON p.category_id = ct.category_id WHERE p.is_customizable = #{isCustomizable} ORDER BY p.created_at DESC
